import { sqliteTable, check, integer, text, uniqueIndex, index, unique } from "drizzle-orm/sqlite-core";
import { sql } from "drizzle-orm";

// Source of truth for the DB schema. Generated by `drizzle-kit pull` against the live v41
// database, then hand-corrected: drizzle-kit 0.31.10's SQLite check-constraint introspection
// attaches every CHECK in the database to every table (and truncates multi-clause SQL text),
// so each check() below was manually reassigned to its real owning table and its SQL text
// restored to match the original `CREATE TABLE` (verified against `sqlite_master`). See
// docs/DATABASE.md for the migration workflow — never hand-edit `src/db/migrations/`, only
// this file, then run `drizzle-kit generate`.

// Retained (not dropped) purely so an existing DB's legacy hash-verification table isn't
// destroyed by a future `generate` — no longer written to; see src/db/migrations.ts.
export const schemaMigrations = sqliteTable("schema_migrations", {
  version: integer().primaryKey(),
  hash: text().notNull(),
});

export const birthdays = sqliteTable(
  "birthdays",
  {
    id: integer().primaryKey({ autoIncrement: true }),
    date: text().notNull(),
    mention: text().notNull(),
    userId: text("user_id"),
    name: text(),
    source: text().default("list").notNull(),
  },
  (table) => [uniqueIndex("idx_birthdays_user").on(table.userId), index("idx_birthdays_date").on(table.date)],
);

