export const eventSignups = sqliteTable(
  "event_signups",
  {
    id: integer().primaryKey({ autoIncrement: true }),
    eventId: integer("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    rawName: text("raw_name").notNull(),
    normalizedName: text("normalized_name").notNull(),
    choice: text().notNull(),
    userId: text("user_id"),
    matchSource: text("match_source").notNull(),
    withdrawnAt: text("withdrawn_at"),
    attendanceStatus: text("attendance_status"),
    firstJoinedAt: text("first_joined_at"),
    lastLeftAt: text("last_left_at"),
    lateMinutes: integer("late_minutes"),
    earlyMinutes: integer("early_minutes"),
    // Drives the event embed's name-list ordering within each choice category: set on first
    // signup, bumped only when `choice` actually changes (see upsertSignupByUserStmt). Defaults
    // to an epoch value for rows that predate this column, so they fall back to `id` order
    // (see the ORDER BY in selectSignupsByEventStmt) until they next change their vote.
    choiceChangedAt: text("choice_changed_at").default("1970-01-01T00:00:00.000Z").notNull(),
  },
  (table) => [
    // Unnamed in the original DDL (SQLite auto-names it sqlite_autoindex_event_signups_N) — this
    // is what upsertSignupByUserStmt's ON CONFLICT(event_id, normalized_name) targets.
    unique().on(table.eventId, table.normalizedName),
    uniqueIndex("idx_event_signups_user_unique").on(table.eventId, table.userId).where(sql`user_id IS NOT NULL`),
    index("idx_event_signups_user").on(table.userId),
    index("idx_event_signups_event").on(table.eventId),
  ],
);

